def normalize_legacy_condition_percentages(apps, schema_editor):
    Barter = apps.get_model('barter_details', 'Barter')
    database = schema_editor.connection.alias

    for barter in Barter.objects.using(database).all().iterator():
        try:
            percentage = int(barter.condition)
        except (TypeError, ValueError):
            continue
        if 0 <= percentage <= 100:
            Barter.objects.using(database).filter(pk=barter.pk).update(
                condition='GOOD',
                condition_percentage=percentage,
            )


